             <button
               type="button"
               data-testid={togetherTestid.confirm}
               disabled={busy}
               onClick={() => {
                 setAsking(false);
                 onBlock?.();
               }}
             >
               {t("Block")}
             </button>
             <button
               type="button"
               className="link-button"
               data-testid={togetherTestid.keep}
               onClick={() => {
                 setAsking(false);
               }}
             >
               {t("Keep")}
             </button>
           </span>
         ) : (
           <span className="together-row__actions">
             …the existing incoming/outgoing children, unchanged except the Block button below…
           </span>
         )}
